void ah_dashboard_draw_icon(struct RastPort *rp,int x,int y,const char *entity,const char *device_class)
{struct Image image;unsigned int i,n;const char *dot=strchr(entity,'.');n=dot ? (unsigned int)(dot-entity):0;i=sizeof(names)/sizeof(names[0])-1;if(device_class&&*device_class){unsigned int k;for(k=0;k<sizeof(names)/sizeof(names[0])-1;++k)if(!strcmp(names[k],device_class)){i=k;break;}}if(i==sizeof(names)/sizeof(names[0])-1)for(i=0;i<sizeof(names)/sizeof(names[0])-1;++i)if(strlen(names[i])==n&&!strncmp(entity,names[i],n))break;memset(&image,0,sizeof(image));image.Width=24;image.Height=24;image.Depth=2;image.ImageData=pixels[i];image.PlanePick=3;DrawImage(rp,&image,x,y);}
